package android.content.res;public class Resources {public android.util.DisplayMetrics metrics=new android.util.DisplayMetrics();public android.util.DisplayMetrics getDisplayMetrics(){return metrics;}public int getIdentifier(String name,String type,String pkg){switch(name){case "play_bar_album_img":return 1;case "ll_song_info":return 2;case "back":return 3;case "prev":return 4;case "play":return 5;case "next":return 6;case "collect":return 7;case "download":return 8;case "playMode":return 9;case "mv":return 10;case "ll_sound":return 11;case "guideline":return 12;case "play_bar_prev":return 21;case "fl_play":return 22;case "play_bar_next":return 23;case "play_bar_colloct":return 24;case "play_bar_lyric":return 25;case "play_bar_playlist":return 26;case "play_bar_play_mode":return 27;case "play_bar_sound":return 28;case "play_bar_time":return 29;case "play_bar_play":return 30;default:return 0;}}}
